:root {
  color-scheme: light;
  --ink: #17201d;
  --muted: #66716c;
  --line: #d9dfdb;
  --soft-line: #e9eeeb;
  --canvas: #f3f5f2;
  --surface: #ffffff;
  --surface-alt: #f8faf8;
  --green: #174f3f;
  --green-dark: #103b2f;
  --green-soft: #e8f2ed;
  --amber: #8a5700;
  --amber-soft: #fff2d7;
  --red: #9a352d;
  --red-soft: #fbe9e6;
  --blue: #245a80;
  --blue-soft: #e8f1f7;
  --shadow: 0 12px 32px rgba(23, 32, 29, 0.08);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 1100px;
  background: var(--canvas);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, Segoe UI, sans-serif;
  font-size: 14px;
  line-height: 1.45;
}

button {
  border: 0;
  font: inherit;
}

button:focus-visible {
  outline: 3px solid rgba(36, 90, 128, 0.24);
  outline-offset: 2px;
}

.app-shell {
  display: grid;
  grid-template-rows: 68px minmax(0, 1fr);
  width: 100%;
  height: 900px;
  max-height: 100vh;
  overflow: hidden;
  background: var(--canvas);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 28px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.brand,
.topbar-actions,
.identity,
.case-heading,
.section-title,
.field-line,
.queue-meta,
.action-row,
.endpoint-row {
  display: flex;
  align-items: center;
}

.brand-mark {
  display: grid;
  width: 34px;
  height: 34px;
  margin-right: 12px;
  place-items: center;
  border-radius: 10px;
  background: var(--green);
  color: white;
  font-weight: 750;
  letter-spacing: -0.03em;
}

.brand-name {
  font-size: 16px;
  font-weight: 720;
  letter-spacing: -0.02em;
}

.brand-context {
  margin-left: 12px;
  padding-left: 12px;
  border-left: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
}

.scope-tag {
  margin-right: 16px;
  padding: 6px 10px;
  border: 1px solid #bfd1c8;
  border-radius: 999px;
  background: var(--green-soft);
  color: var(--green-dark);
  font-size: 12px;
  font-weight: 680;
}

.avatar {
  display: grid;
  width: 32px;
  height: 32px;
  margin-right: 9px;
  place-items: center;
  border-radius: 50%;
  background: #dce4df;
  color: #33443d;
  font-size: 12px;
  font-weight: 750;
}

.identity strong,
.identity span {
  display: block;
}

.identity strong {
  font-size: 13px;
}

.identity span {
  color: var(--muted);
  font-size: 11px;
}

.workspace {
  display: grid;
  grid-template-columns: 286px minmax(540px, 1fr) 326px;
  min-height: 0;
}

.queue-panel,
.trace-panel {
  min-height: 0;
  overflow: auto;
  background: var(--surface);
}

.queue-panel {
  border-right: 1px solid var(--line);
}

.trace-panel {
  border-left: 1px solid var(--line);
}

.panel-heading {
  padding: 22px 20px 16px;
  border-bottom: 1px solid var(--soft-line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--green);
  font-size: 11px;
  font-weight: 760;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.panel-heading h1,
.panel-heading h2,
.case-heading h2,
.decision-card h3,
.section-title h3 {
  margin: 0;
  letter-spacing: -0.025em;
}

.panel-heading h1 {
  font-size: 20px;
}

.panel-heading h2 {
  font-size: 17px;
}

.panel-heading p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.queue-list {
  padding: 10px;
}

.queue-item {
  width: 100%;
  margin: 0 0 8px;
  padding: 14px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: default;
}

.queue-item:hover {
  background: var(--surface-alt);
}

.queue-item.selected {
  border-color: #b8cec3;
  background: var(--green-soft);
  box-shadow: inset 3px 0 0 var(--green);
}

.queue-id {
  color: var(--muted);
  font-size: 11px;
  font-weight: 720;
  letter-spacing: 0.06em;
}

.queue-name {
  margin: 3px 0 8px;
  font-size: 14px;
  font-weight: 720;
}

.queue-meta {
  justify-content: space-between;
  gap: 8px;
}

.time {
  color: var(--muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.status {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 3px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 720;
  white-space: nowrap;
}

.status.missing {
  background: var(--amber-soft);
  color: var(--amber);
}

.status.verify {
  background: var(--blue-soft);
  color: var(--blue);
}

.status.ready {
  background: var(--green-soft);
  color: var(--green);
}

.case-panel {
  min-width: 0;
  overflow: auto;
  padding: 24px 26px 112px;
}

.case-heading {
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
}

.case-heading h2 {
  font-size: 24px;
}

.case-heading p {
  margin: 5px 0 0;
  color: var(--muted);
}

.case-id {
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
  color: var(--muted);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}

.decision-card,
.content-card,
.trace-card {
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface);
  box-shadow: var(--shadow);
}

.decision-card {
  margin-bottom: 16px;
  padding: 20px;
  border-color: #e2c887;
  background: linear-gradient(145deg, #fffdf7 0%, #fff9e9 100%);
  box-shadow: 0 10px 26px rgba(138, 87, 0, 0.08);
}

.decision-card h3 {
  font-size: 18px;
}

.decision-card > p {
  max-width: 680px;
  margin: 7px 0 18px;
  color: #695a38;
}

.recommendation {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid #e7d39d;
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.72);
}

.recommendation-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 10px;
  background: var(--amber-soft);
  color: var(--amber);
  font-size: 18px;
  font-weight: 800;
}

.recommendation strong,
.recommendation span {
  display: block;
}

.recommendation span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.recommendation .status {
  display: inline-flex;
  margin: 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.content-card {
  padding: 18px;
  box-shadow: 0 7px 22px rgba(23, 32, 29, 0.05);
}

.content-card.full-width {
  grid-column: 1 / -1;
}

.section-title {
  justify-content: space-between;
  margin-bottom: 14px;
}

.section-title h3 {
  font-size: 15px;
}

.section-title span {
  color: var(--muted);
  font-size: 11px;
}

.fact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 18px;
}

.fact label,
.handoff-field label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 680;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.fact strong {
  display: block;
  font-size: 13px;
}

.checklist {
  display: grid;
  gap: 10px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.checklist li {
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 10px;
  align-items: start;
  padding: 10px 0;
  border-bottom: 1px solid var(--soft-line);
}

.checklist li:last-child {
  border-bottom: 0;
}

.check {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 50%;
  background: var(--green-soft);
  color: var(--green);
  font-size: 12px;
  font-weight: 800;
}

.check.alert {
  background: var(--amber-soft);
  color: var(--amber);
}

.checklist strong,
.checklist span {
  display: block;
}

.checklist span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.policy-note {
  margin: 0;
  padding: 12px 14px;
  border-left: 3px solid var(--green);
  border-radius: 4px 9px 9px 4px;
  background: var(--surface-alt);
  color: #44504b;
  font-size: 13px;
}

.handoff-fields {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 14px;
}

.field-value {
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-alt);
  color: #33403b;
}

.trace-section {
  padding: 16px;
}

.trace-card {
  margin-bottom: 12px;
  padding: 14px;
  border-radius: 11px;
  box-shadow: none;
}

.trace-card h3 {
  margin: 0 0 11px;
  font-size: 13px;
}

.field-line {
  justify-content: space-between;
  gap: 14px;
  padding: 7px 0;
  border-bottom: 1px solid var(--soft-line);
  font-size: 12px;
}

.field-line:last-child {
  border-bottom: 0;
}

.field-line span:first-child {
  color: var(--muted);
}

.code-value {
  overflow: hidden;
  color: #2e443b;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.endpoint-row {
  justify-content: space-between;
  gap: 8px;
  margin-top: 9px;
  padding: 9px 10px;
  border-radius: 8px;
  background: #f3f6f4;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
}

.endpoint-state {
  color: var(--green);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-weight: 750;
}

.trace-warning {
  padding: 11px 12px;
  border: 1px solid #ead49d;
  border-radius: 9px;
  background: var(--amber-soft);
  color: #6d510f;
  font-size: 11px;
}

.action-bar {
  position: fixed;
  right: 326px;
  bottom: 0;
  left: 286px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 88px;
  padding: 16px 26px;
  border-top: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.97);
  box-shadow: 0 -10px 28px rgba(23, 32, 29, 0.08);
}

.action-guidance strong,
.action-guidance span {
  display: block;
}

.action-guidance strong {
  font-size: 13px;
}

.action-guidance span {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
}

.action-row {
  justify-content: flex-end;
  gap: 9px;
}

.btn {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  color: var(--ink);
  font-size: 12px;
  font-weight: 720;
  white-space: nowrap;
  cursor: pointer;
}

.btn:hover {
  background: var(--surface-alt);
}

.btn.primary {
  border-color: var(--green);
  background: var(--green);
  color: white;
}

.btn.primary:hover {
  background: var(--green-dark);
}

.btn.escalate {
  border-color: #b9cfdd;
  color: var(--blue);
}

.btn:disabled {
  border-color: #e0e4e1;
  background: #eef1ef;
  color: #9ca49f;
  cursor: not-allowed;
}

@media (max-width: 1180px) {
  .workspace {
    grid-template-columns: 250px minmax(510px, 1fr) 290px;
  }

  .action-bar {
    right: 290px;
    left: 250px;
  }

  .action-guidance {
    display: none;
  }
}

