  grid-template-columns: 24px 1fr;
  gap: 10px;
  align-items: start;
  padding: 10px 0;
  border-bottom: 1px solid var(--soft-line);
}

.checklist li:last-child {
  border-bottom: 0;
}

.check {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 50%;
  background: var(--green-soft);
  color: var(--green);
  font-size: 12px;
  font-weight: 800;
}

.check.alert {
  background: var(--amber-soft);
  color: var(--amber);
}

.checklist strong,
.checklist span {
  display: block;
}

.checklist span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.policy-note {
  margin: 0;
  padding: 12px 14px;
  border-left: 3px solid var(--green);
  border-radius: 4px 9px 9px 4px;
  background: var(--surface-alt);
  color: #44504b;
  font-size: 13px;
}

.handoff-fields {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 14px;
}

.field-value {
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-alt);
  color: #33403b;
}

.trace-section {
  padding: 16px;
}

.trace-card {
  margin-bottom: 12px;
  padding: 14px;
  border-radius: 11px;
  box-shadow: none;
}

.trace-card h3 {
  margin: 0 0 11px;
  font-size: 13px;
}

.field-line {
  justify-content: space-between;
  gap: 14px;
  padding: 7px 0;
  border-bottom: 1px solid var(--soft-line);
  font-size: 12px;
}

.field-line:last-child {
  border-bottom: 0;
}

.field-line span:first-child {
  color: var(--muted);
}

.code-value {
  overflow: hidden;
  color: #2e443b;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.endpoint-row {
  justify-content: space-between;
  gap: 8px;
  margin-top: 9px;
  padding: 9px 10px;
  border-radius: 8px;
  background: #f3f6f4;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 10px;
}

.endpoint-state {
  color: var(--green);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-weight: 750;
}

.trace-warning {
  padding: 11px 12px;
  border: 1px solid #ead49d;
  border-radius: 9px;
  background: var(--amber-soft);
  color: #6d510f;
  font-size: 11px;
}

.action-bar {
  position: fixed;
  right: 326px;
  bottom: 0;
  left: 286px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 88px;
  padding: 16px 26px;
  border-top: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.97);
  box-shadow: 0 -10px 28px rgba(23, 32, 29, 0.08);
}

.action-guidance strong,
.action-guidance span {
  display: block;
}

.action-guidance strong {
  font-size: 13px;
}

.action-guidance span {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
}

.action-row {
  justify-content: flex-end;
  gap: 9px;
}

.btn {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  color: var(--ink);
  font-size: 12px;
  font-weight: 720;
  white-space: nowrap;
  cursor: pointer;
}

.btn:hover {
  background: var(--surface-alt);
}

.btn.primary {
  border-color: var(--green);
  background: var(--green);
  color: white;
}

.btn.primary:hover {
  background: var(--green-dark);
}

.btn.escalate {
  border-color: #b9cfdd;
  color: var(--blue);
}

.btn:disabled {
  border-color: #e0e4e1;
  background: #eef1ef;
  color: #9ca49f;
  cursor: not-allowed;
}

@media (max-width: 1180px) {
  .workspace {
    grid-template-columns: 250px minmax(510px, 1fr) 290px;
  }

  .action-bar {
    right: 290px;
    left: 250px;
  }

  .action-guidance {
    display: none;
  }
}
