  <div class="workspace">
    <aside class="queue-panel" aria-label="Intake packet queue">
      <div class="panel-heading">
        <p class="eyebrow">Today</p>
        <h1>Readiness queue</h1>
        <p>3 appointment requests awaiting action</p>
      </div>
      <nav class="queue-list" aria-label="Appointment requests">
        <button class="queue-item selected" type="button" aria-current="true">
          <span class="queue-id">I-4471</span>
          <span class="queue-name">Avery Morgan</span>
          <span class="queue-meta"><span class="status missing">Consent missing</span><span class="time">10:30 AM</span></span>
