          <span class="queue-meta"><span class="status verify">Verify insurance</span><span class="time">1:00 PM</span></span>
        </button>
        <button class="queue-item" type="button">
          <span class="queue-id">I-4473</span>
          <span class="queue-name">Jules Kim</span>
          <span class="queue-meta"><span class="status ready">Ready to schedule</span><span class="time">3:15 PM</span></span>
        </button>
      </nav>
    </aside>

    <section class="case-panel" aria-labelledby="case-title">
      <div class="case-heading">
        <div>
          <p class="eyebrow">New patient consult</p>
          <h2 id="case-title">Avery Morgan</h2>
          <p>Appointment packet pending administrative readiness review</p>
        </div>
        <span class="case-id">intake_packet · I-4471</span>
      </div>

      <article class="decision-card" aria-labelledby="readiness-heading">
        <h3 id="readiness-heading">Not ready to schedule</h3>
        <p>The required signed consent form is missing. Return the intake packet so the form can be completed before an appointment slot is confirmed.</p>
        <div class="recommendation">
          <div class="recommendation-icon" aria-hidden="true">!</div>
          <div><strong>Next administrative action: Return missing forms</strong><span>Reason: Signed consent is required before scheduling.</span></div>
          <span class="status missing">Action required</span>
        </div>
      </article>

      <div class="content-grid">
        <article class="content-card">
          <div class="section-title"><h3>Appointment request</h3><span>Submitted today</span></div>
          <div class="fact-grid">
            <div class="fact"><label>Request</label><strong>New patient consult</strong></div>
            <div class="fact"><label>Requested slot</label><strong>10:30 AM</strong></div>
            <div class="fact"><label>Referral</label><strong>Received</strong></div>
            <div class="fact"><label>Insurance</label><strong>Card image present</strong></div>
          </div>
        </article>

        <article class="content-card">
          <div class="section-title"><h3>Packet requirements</h3><span>2 of 3 complete</span></div>
          <ul class="checklist">
            <li><span class="check" aria-hidden="true">✓</span><div><strong>Referral document</strong><span>Uploaded and attached to the intake packet</span></div></li>
