            <li><span class="check alert" aria-hidden="true">!</span><div><strong>Signed consent</strong><span>Required form has not been received</span></div></li>
          </ul>
        </article>

        <article class="content-card full-width">
          <div class="section-title"><h3>Administrative policy</h3><span>Applies to this review</span></div>
          <p class="policy-note">Schedule only when required administrative forms are complete. Send insurance uncertainty to verification staff. Do not diagnose, triage, or recommend treatment.</p>
        </article>

        <article class="content-card full-width">
          <div class="section-title"><h3>Administrative handoff</h3><span>Prepared from current packet state</span></div>
          <div class="handoff-fields">
            <div class="handoff-field"><label>Next action</label><div class="field-value">Return missing forms</div></div>
            <div class="handoff-field"><label>Reason</label><div class="field-value">Signed consent form is missing before scheduling.</div></div>
          </div>
        </article>
      </div>
    </section>

    <aside class="trace-panel" aria-label="Implementation context">
      <div class="panel-heading">
        <p class="eyebrow">Packet context</p>
        <h2>Data &amp; service trace</h2>
        <p>Source fields supporting this administrative review</p>
      </div>
      <div class="trace-section">
        <section class="trace-card">
          <h3>intake_packet record</h3>
          <div class="field-line"><span>resource_id</span><span class="code-value">intake/I-4471</span></div>
          <div class="field-line"><span>schema_version</span><span class="code-value">1.4</span></div>
          <div class="field-line"><span>packet_status</span><span class="code-value">consent_missing</span></div>
          <div class="field-line"><span>crud_state</span><span class="code-value">review_pending</span></div>
        </section>

        <section class="trace-card">
          <h3>Document fields</h3>
          <div class="field-line"><span>referral.uploaded</span><span class="code-value">true</span></div>
          <div class="field-line"><span>insurance_card.present</span><span class="code-value">true</span></div>
          <div class="field-line"><span>consent.signed</span><span class="code-value">false</span></div>
        </section>

        <section class="trace-card">
          <h3>Service status</h3>
          <div class="endpoint-row"><span>eligibility API</span><span class="endpoint-state">available</span></div>
          <div class="endpoint-row"><span>scheduling endpoint</span><span class="endpoint-state">available</span></div>
          <div class="endpoint-row"><span>tool call result</span><span class="endpoint-state">complete</span></div>
        </section>

        <section class="trace-card">
          <h3>Decision input</h3>
          <div class="field-line"><span>JSON schema</span><span class="code-value">valid</span></div>
          <div class="field-line"><span>prompt template</span><span class="code-value">intake_readiness_v2</span></div>
          <div class="field-line"><span>result</span><span class="code-value">return_missing_forms</span></div>
        </section>

        <div class="trace-warning">Implementation details are shown because this candidate was generated directly from the raw brief; no reviewed activity-model handoff was provided.</div>
      </div>
    </aside>
  </div>

  <footer class="action-bar" aria-label="Administrative actions">
    <div class="action-guidance"><strong>Choose the next administrative action</strong><span>Scheduling remains unavailable until required forms are complete.</span></div>
    <div class="action-row">
      <button class="btn" type="button" disabled>Schedule appointment</button>
      <button class="btn escalate" type="button">Escalate insurance verification</button>
